    """Return the number of prime numbers strictly less than ``n``.
    Handles non‑integer and negative inputs by returning 0.
    Uses the Sieve of Eratosthenes with a bytearray for efficiency.
    """
    try:
        n = int(n)
    except Exception:
        return 0
    if n <= 2:
        return 0
    # Sieve array: 1 means prime candidate.
    is_prime = bytearray(b'\x01') * n
    # 0 and 1 are not prime.
    if n > 0:
        is_prime[0] = 0
    if n > 1:
        is_prime[1] = 0
    import math
    limit = int(math.isqrt(n - 1))
    for p in range(2, limit + 1):
        if is_prime[p]:
            start = p * p
            step = p
            # Mark multiples of p as non‑prime. The slice may be empty.
            is_prime[start:n:step] = b'\x00' * ((n - 1 - start) // step + 1)
    return sum(is_prime)

