def solve(mat):
    # Empty matrix determinant is defined as 1
    if not mat:
        return 1
    n = len(mat)
    # Convert to Fraction for exact arithmetic
    from fractions import Fraction
    a = [[Fraction(x) for x in row] for row in mat]
    det = Fraction(1)
    sign = 1
    for i in range(n):
        # Find pivot
        pivot = None
        for r in range(i, n):
            if a[r][i] != 0:
                pivot = r
                break
        if pivot is None:
            return 0
        if pivot != i:
            a[i], a[pivot] = a[pivot], a[i]
            sign *= -1
        piv_val = a[i][i]
        det *= piv_val
        # Eliminate rows below
        for r in range(i+1, n):
            factor = a[r][i] / piv_val
            for c in range(i, n):
                a[r][c] -= factor * a[i][c]
    return int(det * sign)

