{"task_id": "T33", "code": "def solve(intervals):
    # Normalize intervals: ensure each is a list of two numbers with start <= end
    norm = []
    for iv in intervals:
        if not iv:
            continue
        # Accept list or tuple of length 2
        a, b = iv[0], iv[1]
        if a <= b:
            norm.append([a, b])
        else:
            norm.append([b, a])
    if not norm:
        return []
    # Sort by start
    norm.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = norm[0]
    for s, e in norm[1:]:
        if s <= cur_end:  # overlap or touch
            cur_end = max(cur_end, e)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = s, e
    merged.append([cur_start, cur_end])
    return merged"}

