    """
    if not grid:
        return 0
    visited = set()
    rows = len(grid)
    def neighbors(r, c):
        return [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
            if (i,j) in visited:
