def solve(mat):
    """Return integer determinant of a square matrix (list of lists).
    Empty matrix => 1.
    Uses Bareiss algorithm for exact integer arithmetic.
    """
    if not mat:
        return 1
    n = len(mat)
    # ensure square
    for row in mat:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Make a deep copy to avoid mutating input
    A = [list(map(int, row)) for row in mat]
    det = 1
    for k in range(n-1):
        # pivot check, if zero, swap with a lower row
        if A[k][k] == 0:
            swap_row = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            det = -det
        for i in range(k+1, n):
            for j in range(k+1, n):
                # Bareiss update
                A[i][j] = (A[i][j]*A[k][k] - A[i][k]*A[k][j]) // (A[k-1][k-1] if k>0 else 1)
        # set column entries to zero for cleanliness
        for i in range(k+1, n):
            A[i][k] = 0
    det *= A[n-1][n-1]
    return det

