def solve(intervals):
    # Clean and normalize intervals
    cleaned = []
    for iv in intervals:
        # Ensure we have a sequence with at least two elements
        if iv is None:
            continue
        try:
            a, b = iv[0], iv[1]
        except Exception:
            continue
        # Swap if out of order
        if a <= b:
            cleaned.append([a, b])
        else:
            cleaned.append([b, a])
    if not cleaned:
        return []
    # Sort by start
    cleaned.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = cleaned[0]
    for s, e in cleaned[1:]:
        if s <= cur_end:  # overlap or touch
            cur_end = max(cur_end, e)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = s, e
    merged.append([cur_start, cur_end])
    return merged

