def solve(grid):
    """Count islands in a grid of 0s and 1s.
    Handles ragged (non-rectangular) grids and empty rows.
    Cells connect up, down, left, right.
    """
    if not grid:
        return 0
    visited = set()
    rows = len(grid)
    def neighbors(r, c):
        return [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if grid[i][j] != 1:
                continue
            visited.add((i, j))
            for ni, nj in neighbors(i, j):
                stack.append((ni, nj))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

