def solve(coins, amount):
    """Return the minimum number of coins needed to make up *amount* using unlimited coins
    from the list *coins*. If it is not possible, return -1.
    Handles edge cases such as empty coin list and amount zero.
    """
    # Validate inputs
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Filter out non‑positive coin values; they cannot contribute positively.
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    # Dynamic programming: dp[i] = min coins to make i, initialize with a large sentinel.
    max_val = amount + 1  # sentinel larger than any possible answer
    dp = [max_val] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for c in coins:
            if c <= i:
                # If using coin c, we need dp[i-c] + 1 coins.
                if dp[i - c] + 1 < dp[i]:
                    dp[i] = dp[i - c] + 1
    return dp[amount] if dp[amount] != max_val else -1

